n', 'native_english', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, '53', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '10.1016/j.gerinurse.2023.07.014', '37540908', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 3, 'clinical', NULL, NULL, NULL, NULL, 'COMPLETE', 'VERIFIED', 'RESOLVED', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, '2026-10-30 21:41', 'session_2026-10-30-ramp-spec-pages-rebuild', '2026-10-30 21:41', 'session_2026-10-30-ramp-spec-pages-rebuild', 'crossref', NULL, 1, NULL, '141-145', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'CORRECTED', '2026-10-30 doi_resolution_outcome CORRECTED (the DOI''s Crossref work record was retrieved (HTTP 200) and persisted in retrieval-log/session_2026-10-30-ramp-spec-pages-rebuild; title, year and container agree with the stored row). Replaced text was: None', NULL, NULL, NULL, NULL, 'lower_control', 'pending', 'pending', NULL, NULL, NULL, NULL, 'CLOSED', 'tool', NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-070', 'EG', 'P2', 'OPEN', 'research', 'parameter 12, ramp run length', 'RISE-BASED LANDING SPACING HAS NO PARAMETER. Parameter 12 (TERM-091) holds limits stated as a horizontal run or going between landings (UK, IE, DE, ES, PT, FR, SG, NZ). Several codes state the same protection as a maximum vertical rise between landings instead, and those figures are NOT written: US ADA 2010 405.6 (30 in, REF-00987), JP (REF-00990, a rise of 75 cm per landing; not read this session), KR REF-01031 (0.75 m, read), FI REF-01017 (500 mm continuous rise before a 2000 mm landing, read), SE REF-01024 (0.5 m between landings, read), NL REF-01021 (1 m of rise per ramp, read), UG REF-01010 (3600 mm combined rise, read). Writing a rise under parameter 12 would put a vertical length beside horizontal ones in one unit family, and the engine would compose them (most accommodating = smallest figure). Observing the phrase to mint a parameter adds adjudication debt the owner rules on (OR-17). Not filed as a parameter here. Re-derive the list by searching the held texts for landing in each language.', '2026-10-30 21:43', 'session_2026-10-30-ramp-spec-pages-rebuild', '2026-10-30 21:43', 'session_2026-10-30-ramp-spec-pages-rebuild', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-071', 'EG', 'P3', 'OPEN', 'research', 'term TERM-092, intermediate landing', 'LANDING DIMENSIONS ARE UNRECORDED AS ROWS. TERM-092 (intermediate landing) is a term but not a parameter, so the landing length and depth that the read sources state are in notes only, not extractions: DE 150 cm (REF-00988), PT 1.5 m (REF-01032, 2.5.6), ES 1.50 m (REF-01027, 4.3.3), SG 1500 mm depth (REF-00139, 4.6.5.2(a)), NZ 1200 mm minimum and 1500 mm where possible (REF-01016, 6.5.2), UG 1500 mm at top and bottom (REF-01010). Promoting TERM-092 needs add-parameter and, for a direction, a source that states one. Not done: the request was spacing, and the promotion is a vocabulary act.', '2026-10-30 21:43', 'session_2026-10-30-ramp-spec-pages-rebuild', '2026-10-30 21:43', 'session_2026-10-30-ramp-spec-pages-rebuild', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "evidence_population_match" ("match_id", "source_ref", "target_population", "study_population", "sample_size", "match_grade", "mismatch_note", "created_at", "created_by_session", "ref_id", "gap_id") VALUES ('session_2026-10-30-ramp--REF-00139-MOB', 'REF-00139', 'MOB', 'no participants; a regulatory text (Singapore Code on Accessibility 2025, v1.1)', NULL, 'PROXY', 'PROXY by construction: a code asserts a figure; it does not study a population. Same grading as the other codes of the slug (REF-01031, REF-01032).', '2026-10-30 21:43', 'session_2026-10-30-ramp-spec-pages-rebuild', 'REF-00139', NULL);
INSERT INTO "evidence_population_match" ("match_id", "source_ref", "target_population", "study_population", "sample_size", "match_grade", "mismatch_note", "created_at", "created_by_session", "ref_id", "gap_id") VALUES ('session_2026-10-30-ramp--REF-01033-MOB', 'REF-01033', 'MOB', 'sixteen unimpaired people (non-wheelchair users) propelling a wheelchair 120 m at 8%', 16, 'PROXY', 'General-population participants: the distance-effect result (effort and heart rate rising with distance) is a proxy for wheelchair users, not their measurement. It is the only held source that measures effort against distance on a slope.', '2026-10-30 21:43', 'session_2026-10-30-ramp-spec-pages-rebuild', 'REF-01033', NULL);
INSERT INTO "evidence_population_match" ("match_id", "source_ref", "target_population", "study_population", "sample_size", "match_grade", "mismatch_note", "created_at", "created_by_session", "ref_id", "gap_id") VALUES ('session_2026-10-30-ramp--REF-01033-SCI', 'REF-01033', 'SCI', 'five wheelchair users with cervical cord injury, 3 m laboratory slope at 5 to 12.5%', 5, 'PARTIAL', 'Matches the group on the gradient test, but n=5 and the abstract reports no result for them; no threshold can rest on it.', '2026-10-30 21:43', 'session_2026-10-30-ramp-spec-pages-rebuild', 'REF-01033', NULL);
INSERT INTO "evidence_population_match" ("match_id", "source_ref", "target_population", "study_population", "sample_size", "match_grade", "mismatch_note", "created_at", "created_by_session", "ref_id", "gap_id") VALUES ('session_2026-10-30-ramp--REF-01034-MOB', 'REF-01034', 'MOB', '27 adults: manual wheelchair users, power wheelchair users, and people with vision impairment using a cane or service animal; transit-bus boarding ramps', 27, 'PARTIAL', 'Wheelchair users are in the sample; the abstract says it was small and excluded scooter and ambulation-aid users, and the ramps are vehicle ramps, so slopes steeper than a building ramp are in question.', '2026-10-30 21:43', 'session_2026-10-30-ramp-spec-pages-rebuild', 'REF-01034', NULL);
INSERT INTO "evidence_population_match" ("match_id", "source_ref", "target_population", "study_population", "sample_size", "match_grade", "mismatch_note", "created_at", "created_by_session", "ref_id", "gap_id") VALUES ('session_2026-10-30-ramp--REF-01035-MS', 'REF-01035', 'MS', '18 ambulatory people with multiple sclerosis (mean EDSS 2.9) and 23 healthy adults, treadmill', 18, 'PARTIAL', 'People with MS, but ambulatory and mildly affected (EDSS 2.9); those who use a wheelchair or other aid on ramps are not in the sample. Treadmill, not a built ramp.', '2026-10-30 21:43', 'session_2026-10-30-ramp-spec-pages-rebuild', 'REF-01035', NULL);
INSERT INTO "evidence_population_match" ("match_id", "source_ref", "target_population", "study_population", "sample_size", "match_grade", "mismatch_note", "created_at", "created_by_session", "ref_id", "gap_id") VALUES ('session_2026-10-30-ramp--REF-01036-MOB', 'REF-01036', 'MOB', '26 older adults walking up and down an incline with a cane and a rolling walker', 26, 'PARTIAL', 'Walking-device users, but selected as ''qualified'' older adults; the lens MOB is assigned from device use, and no wheelchair users are in the sample. Incline angle not given in the abstract.', '2026-10-30 21:43', 'session_2026-10-30-ramp-spec-pages-rebuild', 'REF-01036', NULL);
