INSERT INTO "search_executions" ("exec_id", "slug", "parameter_id", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session", "identity_code", "icf_code", "needs_code", "medical_code") VALUES (192, 'accessible-circulation-geometry', NULL, 'SG', 'EN', NULL, NULL, NULL, 'https://go.gov.sg/bca-coa2025 (short link to the Building and Construction Authority''s Code on Accessibility in the Built Environment 2025; lead from workplan/2026-10-30-ramp-spec-pages/reports/research-batch-ramp-slopes-2026-10-29__findings.md sections 1 and 5)', NULL, 'web', 'scoping', NULL, 1, 1, 1, 'none', NULL, NULL, 1, 'session_2026-10-30-ramp-spec-pages-rebuild', '2026-10-30 21:42', 'Resolved to file.go.gov.sg/bca-coa2025.pdf, 116 pages; its history of amendments names Version 1.1 (1 March 2026), superseding v1.0 (7 April 2025). Table 4 (p.43) and Table 5 (p.47) were rendered and read from the page image as well as the text layer; both agree with the earlier hand reading. The stash already held this URL as REF-00139 (pre-reset, REFERENCE-ONLY, titled as Chapter 8 wayfinding); the source is admitted under that id, not a second one (R9a).', 0, 'BACKFILLED after the fetch (the retrieval was logged as it ran; this row was not). Expectation as it would have been written: the link resolves to the current Code (2025), which states a gradient table for changes in level and a table of maximum ramp run between landings; the earlier session''s reading (rise threshold 175 mm; runs 6/9/12/15/18 m at 1:12/1:14/1:16/1:20/1:24) is a hand reading and may be wrong in alignment.', 'lead-index', NULL, NULL, '2026-10-30 21:42', 'session_2026-10-30-ramp-spec-pages-rebuild', NULL, NULL, NULL, NULL);
INSERT INTO "search_executions" ("exec_id", "slug", "parameter_id", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session", "identity_code", "icf_code", "needs_code", "medical_code") VALUES (193, 'accessible-circulation-geometry', NULL, NULL, 'EN', NULL, NULL, NULL, 'Crossref bibliographic title search for four studies listed in workplan/2026-10-30-ramp-spec-pages/reports/research-batch-ramp-slopes-2026-10-29__findings.md section 2 (items 2, 5, 8, 9): Hashizume 2015, Lenker 2016, Har-Nir 2022/23, Liu 2023; then DOI work records and PubMed records for each', NULL, 'crossref', 'scoping', NULL, 4, 4, 4, 'none', NULL, NULL, 1, 'session_2026-10-30-ramp-spec-pages-rebuild', '2026-10-30 21:42', 'All four resolved. Differences from the earlier hand-typed list: Har-Nir is dated 2023 (Crossref issued 2023-03; vol 59 issue 1), not 2022; Hashizume 2015 is a proceedings chapter whose Crossref abstract also reports a 120 m, 8% slope study of 16 unimpaired people (effort and heart rate rising with distance), which the earlier findings did not record. Not admitted from the same list: Choi 2015 and Lay 2005 (healthy-adult proxies), Pierret 2014 and Flemmer 2026 (cross-slope, not running slope), Jahanian 2022 (geared-wheel technology on one ramp), Leone 2016 and Rooney 2021 (MS fatigue and oxygen cost of walking, no slope). Chow 2009, Bertocci 2018 and Sanford 1997 are already held as REF-00979, REF-00983 and REF-00980; IE TGD M 2022 as REF-01018.', 0, 'BACKFILLED after the retrievals (the retrievals were logged as they ran; this row was not). Expectation as it would have been written: each title resolves to one DOI whose work record agrees with the earlier session''s hand-typed citation; abstracts are available for all four; the earlier findings restate the abstracts.', 'lead-index', NULL, NULL, '2026-10-30 21:42', 'session_2026-10-30-ramp-spec-pages-rebuild', NULL, NULL, NULL, NULL);
INSERT INTO "search_executions" ("exec_id", "slug", "parameter_id", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session", "identity_code", "icf_code", "needs_code", "medical_code") VALUES (194, 'accessible-circulation-geometry', NULL, NULL, 'EN', NULL, 'co1', NULL, '(wheelchair users[tiab] OR disabled people[tiab] OR mobility disability[tiab]) AND (ramp[tiab] OR ramps[tiab]) AND (lived experience[tiab] OR participatory[tiab] OR qualitative[tiab] OR co-design[tiab] OR focus group*[tiab] OR interview*[tiab])', NULL, 'pubmed', 'scoping', NULL, 6, 6, 0, 'none', NULL, NULL, 1, 'session_2026-10-30-ramp-spec-pages-rebuild', '2026-10-30 21:42', '6 hits (esearch 2026-10-30). One is already held (REF-01006, participatory accessibility audits, India). The rest are about wheelability mapping, a winter-mobility course, anti-rollback devices and wheelchair-skills priorities; none states a ramp slope or run from lived experience. Zero new admissions. Query-shape failure is the likelier explanation of the low count than genuine absence: PubMed does not index the disability-organisation and grey literature where Co-1 work on ramps would sit.', 0, 'BACKFILLED: the query was run before this row was written, so this prior is post hoc. Expected: few hits, because PubMed AND-chains every term and lived-experience work on ramps is mostly in grey literature and disability-organisation reports PubMed does not index; the earlier session found 29 Co-1 sources in the old library and none on ramps.', 'planned', NULL, NULL, '2026-10-30 21:42', 'session_2026-10-30-ramp-spec-pages-rebuild', NULL, NULL, NULL, NULL);
INSERT INTO "search_executions" ("exec_id", "slug", "parameter_id", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session", "identity_code", "icf_code", "needs_code", "medical_code") VALUES (195, 'accessible-circulation-geometry', NULL, NULL, 'EN', NULL, NULL, NULL, 'wheelchair[tiab] AND (ramp[tiab] OR ramps[tiab]) AND (landing[tiab] OR landings[tiab] OR rest[tiab] OR resting[tiab] OR fatigue[tiab] OR exertion[tiab])', NULL, 'pubmed', 'scoping', NULL, 13, 13, 0, 'none', NULL, NULL, 1, 'session_2026-10-30-ramp-spec-pages-rebuild', '2026-10-30 21:42', '13 hits (esearch 2026-10-30, titles screened). None measures effort or fatigue against ramp length with rests; three are already held in substance (REF-00980 Sanford 1997, REF-01008-era literature) or are device studies (geared wheel, anti-rollback). Zero admissions. The distance-effect study (Hashizume 2015) came from the lead list, not from this search, so this query-shape did not find it: its abstract says ''slope'', ''uphill'' and ''distance'', not ''landing'' or ''rest''. || CORRECTED 2026-10-30: CORRECTION: the phrase ''three are already held in substance (REF-00980 Sanford 1997, REF-01008-era literature)'' is wrong. One hit is already held: PMID 10168021 is Sanford 1997, REF-00980. The others are device, physiology or unrelated studies, none held, none admitted.', 0, 'BACKFILLED: run before this row was written, so post hoc. Expected: little or nothing on landing spacing, since the question is a design-code one and codes are not indexed in PubMed; some effort-on-ramp physiology.', 'planned', NULL, NULL, '2026-10-30 21:42', 'session_2026-10-30-ramp-spec-pages-rebuild', NULL, NULL, NULL, NULL);
INSERT INTO "source_scans" ("scan_id", "ref_id", "mode", "catalogue_version", "target_parameter_id", "text_scope", "pages_read", "pages_total", "file_sha256", "open_pass_done", "method", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (1, 'REF-00139', 'catalogue', 12, NULL, 'full', 116, 116, '6ef9ca54ca4533749c5dff13f7a9ae8cc14bd9c98b4f3fde3c5a09ca7466b8cb', 0, 'pre-screen', 'The derived text holds all 116 pages. It was NOT read end to end: each of the ten active parameters was searched for in the text, the passages found were read, and Tables 3, 4 and 5 were checked against the page image. LRV contrast: the Code requires colour contrast between door and frame without a figure (recorded as absent). Colour temperature and reverberation time: no passage states a value. The open pass for quantities the catalogue lacks was not done.', '2026-10-30 21:43', 'session_2026-10-30-ramp-spec-pages-rebuild', '2026-10-30 21:43', 'session_2026-10-30-ramp-spec-pages-rebuild');
