INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (122, 'REF-01030', NULL, 3, 'MOB', NULL, NULL, NULL, 'FR', 'ramp', 'numerical', '2', '% (slope above which the guide recommends a rest landing every 10 m over a long distance)', 'Il est recommandé de prévoir un palier de repos tous les 10 m dès qu’une pente supérieure à 2 % est aménagée sur une longue distance, sans attendre le seuil réglementaire de 5 %', 'Guide illustré, Accessibilité des ERP / IOP, cheminement extérieur, recommandations', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, 'recommandations', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'preliminary', NULL, 'Threshold at which the recommendation applies, not a limit on gradient.', '2026-10-30 21:42', 'session_2026-10-30-ramp-spec-pages-rebuild', '2026-10-30 21:42', 'session_2026-10-30-ramp-spec-pages-rebuild', 'condition', '>');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (123, 'REF-00992', NULL, 12, 'MOB', NULL, NULL, NULL, 'UK', 'ramp', 'numerical', '10', 'm maximum going (horizontal length) of any ramp flight', 'no flight has a going greater than 10m, or a rise of more than 500mm', 'Approved Document M Volume 2, paragraph 1.26 c.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, '1.26', NULL, NULL, 'c', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'preliminary', NULL, 'Absolute cap: it applies at every gradient. Table 1 in the same paragraph lets the going lengthen only as the gradient gentles, to 1:20 at 10 m; those goings are held on parameter 3 (extractions 25, 26). Rest landings are named in the preceding text.', '2026-10-30 21:42', 'session_2026-10-30-ramp-spec-pages-rebuild', '2026-10-30 21:42', 'session_2026-10-30-ramp-spec-pages-rebuild', 'claim', '<=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (124, 'REF-01018', NULL, 12, 'MOB', NULL, NULL, NULL, 'IE', 'ramp', 'numerical', '10', 'm maximum going of a flight at gradient 1:20 (Table 2)', 'Table 2 Limits for Ramp Gradients and Lengths Maximum Going of a Flight Maximum Gradient Maximum Rise Not exceeding 10 m 1:20 500 mm Not exceeding 5 m 1:15 333 mm Not exceeding 2 m 1:12 166 mm', 'Technical Guidance Document M 2022, Table 2', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, '1.1.3.4', NULL, NULL, 'Table 2', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'preliminary', NULL, 'Row "Not exceeding 10 m / 1:20 / 500 mm". The steeper rows (5 m at 1:15, 2 m at 1:12) are goings at which a steeper gradient is permitted and are not repeated here; extraction 81 holds the gradient.', '2026-10-30 21:42', 'session_2026-10-30-ramp-spec-pages-rebuild', '2026-10-30 21:42', 'session_2026-10-30-ramp-spec-pages-rebuild', 'claim', '<=');
