INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (130, 'REF-00988', NULL, 12, 'MOB', NULL, NULL, NULL, 'DE', 'ramp', 'numerical', '6', 'm maximum length of a ramp run before a landing', 'Rampenläufe dürfen max. 6 m lang sein. Danach muss ein Podest vorgesehen werden, das mindestens 150 cm lang ist.', 'DGUV Fachinfoblatt Teil 2 Kapitel 4.3', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, '4.3', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'preliminary', NULL, 'Secondary (T5) guidance; the same paragraph gives the maximum slope 6 % and a landing at least 150 cm long. [VERBATIM-EXEMPT: the persisted page is HTML with named character entities (Rampenl&auml;ufe d&uuml;rfen max. 6 m lang sein); the quote is the entity-decoded text and the only mismatch is the entity spelling of a-umlaut and u-umlaut]', '2026-10-30 21:42', 'session_2026-10-30-ramp-spec-pages-rebuild', '2026-10-30 21:42', 'session_2026-10-30-ramp-spec-pages-rebuild', 'claim', '<=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (131, 'REF-01016', NULL, 12, 'MOB', NULL, NULL, NULL, 'NZ', 'ramp', 'numerical', '9000', 'mm maximum interval between landings on a ramp', 'Ramps require level platforms or landings at the top and bottom, wherever there is a change in direction, wherever doors open off them and at intervals not exceeding 9000 mm', 'NZS 4121:2001, 6.5.1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, '6.5', '6.5.1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'preliminary', NULL, 'Edition held is 2001; whether it is the current edition is not established here (REF-01016 is UNVERIFIED). Landings are at least 1200 mm (6.5.2), 1500 mm where possible.', '2026-10-30 21:42', 'session_2026-10-30-ramp-spec-pages-rebuild', '2026-10-30 21:42', 'session_2026-10-30-ramp-spec-pages-rebuild', 'claim', '<=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (132, 'REF-01027', NULL, 12, 'MOB', NULL, NULL, NULL, 'ES', 'ramp', 'numerical', '9', 'm maximum length of a ramp section (tramo), horizontal projection, on an accessible route', 'Los tramos tendrán una longitud de 15 m como máximo, excepto si la rampa pertenece a itinerarios accesibles, en cuyo caso la longitud del tramo será de 9 m, como máximo', 'DB SUA, SUA 1, 4.3.2 apartado 1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, 'SUA 1', '4.3.2', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'preliminary', NULL, 'General limit 15 m; 9 m on accessible routes. Parking ramps shared by vehicles and people are not limited.', '2026-10-30 21:42', 'session_2026-10-30-ramp-spec-pages-rebuild', '2026-10-30 21:42', 'session_2026-10-30-ramp-spec-pages-rebuild', 'claim', '<=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (133, 'REF-01028', NULL, 12, 'MOB', NULL, NULL, NULL, 'ES', 'ramp', 'numerical', '9', 'm maximum length of a ramp section at slope 8%, horizontal projection', 'La pendiente longitudinal máxima será del 10% para tramos de hasta 3,00 m de longitud, y del 8% para tramos de hasta 9,00 m de longitud, medidos en proyección horizontal.', 'Orden TMA/851/2021, art. 14 apartado 2 c)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, 'art. 14', NULL, '2', 'c', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'preliminary', NULL, 'Public urban space. The 10% / 3,00 m tier is not repeated here; extraction 100 holds the slope.', '2026-10-30 21:42', 'session_2026-10-30-ramp-spec-pages-rebuild', '2026-10-30 21:42', 'session_2026-10-30-ramp-spec-pages-rebuild', 'claim', '<=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (134, 'REF-01032', NULL, 12, 'MOB', NULL, NULL, NULL, 'PT', 'ramp', 'numerical', '10', 'm maximum horizontal projection of a ramp at gradient not above 6%', 'Ter uma inclinação não superior a 6 %, vencer um desnível não superior a 0,6 m e ter uma projecção horizontal não superior a 10 m', 'Decreto-Lei 163/2006, Anexo, secção 2.5, ponto 2.5.1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, '2.5', '2.5.1', NULL, '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'preliminary', NULL, 'Interpolated values permitted. Point 2.5.5 requires a resting platform where the projection exceeds the figure for the gradient, at the base and top of each flight and at changes of direction.', '2026-10-30 21:42', 'session_2026-10-30-ramp-spec-pages-rebuild', '2026-10-30 21:42', 'session_2026-10-30-ramp-spec-pages-rebuild', 'claim', '<=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (135, 'REF-01032', NULL, 12, 'MOB', NULL, NULL, NULL, 'PT', 'ramp', 'numerical', '5', 'm maximum horizontal projection of a ramp at gradient not above 8%', 'Ter uma inclinação não superior a 8 %, vencer um desnível não superior a 0,4 m e ter uma projecção horizontal não superior a 5 m', 'Decreto-Lei 163/2006, Anexo, secção 2.5, ponto 2.5.1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, '2.5', '2.5.1', NULL, '2', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'preliminary', NULL, 'Interpolated values permitted; see the 6% row.', '2026-10-30 21:42', 'session_2026-10-30-ramp-spec-pages-rebuild', '2026-10-30 21:42', 'session_2026-10-30-ramp-spec-pages-rebuild', 'claim', '<=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (136, 'REF-01030', NULL, 12, 'MOB', NULL, NULL, NULL, 'FR', 'ramp', 'numerical', '10', 'm maximum spacing of rest landings (paliers de repos) on an inclined plane of slope 5% or more', 'En cas de plan incliné de pente supérieure ou égale à 5 %, un palier de repos est nécessaire tous les 10 m.', 'Guide illustré, Accessibilité des ERP / IOP, cheminement extérieur', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, 'plan incliné', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'preliminary', NULL, 'Required. A rest landing is also required at the top and bottom of every inclined plane whatever its length.', '2026-10-30 21:42', 'session_2026-10-30-ramp-spec-pages-rebuild', '2026-10-30 21:42', 'session_2026-10-30-ramp-spec-pages-rebuild', 'claim', '<=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (137, 'REF-01030', NULL, 12, 'MOB', NULL, NULL, NULL, 'FR', 'ramp', 'numerical', '10', 'm recommended spacing of rest landings once any slope above 2% is laid over a long distance', 'Il est recommandé de prévoir un palier de repos tous les 10 m dès qu’une pente supérieure à 2 % est aménagée sur une longue distance, sans attendre le seuil réglementaire de 5 %', 'Guide illustré, Accessibilité des ERP / IOP, cheminement extérieur, recommandations', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, 'recommandations', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'preliminary', NULL, 'A recommendation, stated against the regulatory threshold of 5%: the guide advises resting at the same spacing from a gentler slope than the rule requires.', '2026-10-30 21:42', 'session_2026-10-30-ramp-spec-pages-rebuild', '2026-10-30 21:42', 'session_2026-10-30-ramp-spec-pages-rebuild', 'claim', '<=');
