INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (139, 'REF-00139', NULL, 4, 'MOB', NULL, NULL, NULL, 'SG', 'ramp', 'numerical', '1500', 'mm minimum width of the primary accessible route in residential, office, hotel, school, factory and similar buildings, with passing spaces (4.2.1.2)', 'Purpose-built workers’ dormitories 1500 mm* *Passing spaces in accordance with clause 4.2.1.2 must be provided.', 'Code on Accessibility in the Built Environment 2025, 4.2.1.1(a), Table 3', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, '4.2', '4.2.1', NULL, 'a', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'preliminary', NULL, 'Table 3 lists the building types; the 1500 mm applies to all of them only with passing spaces of 1800 mm by 1800 mm at intervals of at most 25 m (4.2.1.2).', '2026-10-30 21:42', 'session_2026-10-30-ramp-spec-pages-rebuild', '2026-10-30 21:42', 'session_2026-10-30-ramp-spec-pages-rebuild', 'claim', '>=');
