INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (143, 'REF-00139', NULL, 6, 'MOB', NULL, NULL, NULL, 'SG', 'ramp', 'numerical', '30', 'N maximum force at the leading edge to operate a swing door, at 0 degrees', 'The force, measured at the leading edge of the door to operate swing doors must not be more than: (a) 30 N at 0o; and (b) 20 N at 30o.', 'Code on Accessibility in the Built Environment 2025, 4.4.10.1(a)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, '4.4', '4.4.10', NULL, 'a', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'preliminary', NULL, 'Does not apply to latch bolts or other devices that hold the door closed.', '2026-10-30 21:42', 'session_2026-10-30-ramp-spec-pages-rebuild', '2026-10-30 21:42', 'session_2026-10-30-ramp-spec-pages-rebuild', 'claim', '<=');
