INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (148, 'REF-00139', NULL, 11, 'MOB', NULL, NULL, NULL, 'SG', 'ramp', 'numerical', '2000', 'mm minimum clear headroom in pedestrian areas', 'The minimum clear headroom in pedestrian areas such as walkways, halls, corridors, passageways or aisles must be 2000 mm.', 'Code on Accessibility in the Built Environment 2025, 4.3.1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, '4.3', '4.3.1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'preliminary', NULL, 'Current edition (v1.1).', '2026-10-30 21:42', 'session_2026-10-30-ramp-spec-pages-rebuild', '2026-10-30 21:42', 'session_2026-10-30-ramp-spec-pages-rebuild', 'claim', '>=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (149, 'REF-01033', NULL, 12, NULL, NULL, 'A-EFFORT', NULL, NULL, 'long slope, 120 m at 8%, laboratory-measured', 'qualitative', 'the extremely high exercise intensity at a final interval', NULL, 'A mean oxygen uptake and heart rate were increased as the distance increased and their results indicated the extremely high exercise intensity at a final interval that were 1.2liter /min and 152bpm.', 'Abstract (Crossref record)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, 'abstract', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'skim', 'preliminary', NULL, 'Setting per the abstract: a 120 m, 8% slope. PROXY: sixteen unimpaired subjects (non-wheelchair users) propelled a wheelchair; the abstract gives no figure for wheelchair users on the long slope. It is the only held source measuring effort against distance on a slope, which is the quantity a rest landing interrupts. Abstract read only (no full text); skimmed, so the finding sets no value and confirms nothing.', '2026-10-30 21:42', 'session_2026-10-30-ramp-spec-pages-rebuild', '2026-10-30 21:42', 'session_2026-10-30-ramp-spec-pages-rebuild', 'finding', NULL);
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (150, 'REF-01033', NULL, 3, 'SCI', NULL, NULL, NULL, NULL, 'laboratory slope, 3 m', 'range', '5 to 12.5', '% gradient tested, 3 m long, five wheelchair users with cervical cord injury', 'five wheelchair users with cervical cord injury were examined to evaluate the influence of different gradients (5%, 6.7%, 8.3%, 10% and 12.5%) with 3m length in laboratory', 'Abstract (Crossref record)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, 'abstract', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'skim', 'preliminary', NULL, 'The tested gradients are the condition; the abstract reports no result for this group, so no finding is recorded for it. Abstract read only (no full text); skimmed, so the finding sets no value and confirms nothing.', '2026-10-30 21:42', 'session_2026-10-30-ramp-spec-pages-rebuild', '2026-10-30 21:42', 'session_2026-10-30-ramp-spec-pages-rebuild', 'condition', 'between');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (151, 'REF-01034', NULL, 3, 'MOB', NULL, NULL, NULL, NULL, 'transit bus boarding ramp (vehicle, not a building)', 'qualitative', 'usable and acceptable for most participants', NULL, 'The 1:8 and 1:12 slopes were usable and acceptable for most participants.', 'Abstract (landing page)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, 'abstract', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'skim', 'preliminary', NULL, 'Lens MOB is the wheelchair users among the participants; the sample also included people with vision impairment. 27 adults: manual wheelchair users, power wheelchair users, and people with vision impairment using a cane or service animal; four slopes, the abstract names 1:4, 1:8 and 1:12 only. Abstract read only (no full text); skimmed, so the finding sets no value and confirms nothing.', '2026-10-30 21:42', 'session_2026-10-30-ramp-spec-pages-rebuild', '2026-10-30 21:42', 'session_2026-10-30-ramp-spec-pages-rebuild', 'finding', NULL);
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (152, 'REF-01034', NULL, 3, 'MOB', NULL, NULL, NULL, NULL, 'transit bus boarding ramp (vehicle, not a building)', 'qualitative', 'too steep for safe unassisted boarding and disembarking', NULL, 'The data indicate that the 1:4 slope is too steep for safe unassisted boarding and disembarking.', 'Abstract (landing page)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, 'abstract', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'skim', 'preliminary', NULL, 'Lens MOB is the wheelchair users among the participants; the sample also included people with vision impairment. A vehicle boarding ramp, so a steeper slope than a building ramp is in question. Abstract read only (no full text); skimmed, so the finding sets no value and confirms nothing.', '2026-10-30 21:42', 'session_2026-10-30-ramp-spec-pages-rebuild', '2026-10-30 21:42', 'session_2026-10-30-ramp-spec-pages-rebuild', 'finding', NULL);
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (153, 'REF-01034', NULL, 3, 'MOB', NULL, NULL, NULL, NULL, 'transit bus boarding ramp (vehicle, not a building)', 'qualitative', 'lacked the strength needed for unassisted ascent', NULL, 'Many manual wheelchair users lacked the strength needed for unassisted ascent.', 'Abstract (landing page)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, 'abstract', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'skim', 'preliminary', NULL, 'Which slopes are meant is not stated in the abstract. Abstract read only (no full text); skimmed, so the finding sets no value and confirms nothing.', '2026-10-30 21:42', 'session_2026-10-30-ramp-spec-pages-rebuild', '2026-10-30 21:42', 'session_2026-10-30-ramp-spec-pages-rebuild', 'finding', NULL);
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (154, 'REF-01035', NULL, 3, 'MS', NULL, NULL, NULL, NULL, 'treadmill, level, uphill and downhill walking', 'qualitative', 'most demanding effort was during uphill walking', NULL, 'The most demanding effort was during uphill walking, with pwMS rating it more demanding compared with the healthy controls.', 'Abstract (PubMed record 36458477)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, 'abstract', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'skim', 'preliminary', NULL, 'Eighteen ambulatory people with multiple sclerosis (mean EDSS 2.9) and 23 healthy adults; slope not stated in the abstract. The abstract also reports that perceived effort did not follow energy expenditure. Abstract read only (no full text); skimmed, so the finding sets no value and confirms nothing.', '2026-10-30 21:42', 'session_2026-10-30-ramp-spec-pages-rebuild', '2026-10-30 21:42', 'session_2026-10-30-ramp-spec-pages-rebuild', 'finding', NULL);
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (155, 'REF-01035', NULL, 3, 'MS', NULL, 'A-EFFORT', NULL, NULL, 'treadmill, level, uphill and downhill walking', 'qualitative', 'describe the effort of walking on different slopes higher than normal', NULL, 'pwMS describe the effort of walking on different slopes higher than normal, regardless of the energy expenditure values.', 'Abstract (PubMed record 36458477)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, 'abstract', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'skim', 'preliminary', NULL, 'Abstract read only (no full text); skimmed, so the finding sets no value and confirms nothing.', '2026-10-30 21:42', 'session_2026-10-30-ramp-spec-pages-rebuild', '2026-10-30 21:42', 'session_2026-10-30-ramp-spec-pages-rebuild', 'finding', NULL);
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (156, 'REF-01036', NULL, 3, 'MOB', NULL, NULL, NULL, NULL, 'incline walking, rolling walker (RW) and cane', 'qualitative', 'no differences were seen with cane use', NULL, 'With the RW use, downward walking show a faster velocity, higher cadence, less stance time, bigger steps and strides than upward walking (p≤.05); but no differences were seen with cane use.', 'Abstract (PubMed record 37540908)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, 'abstract', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'skim', 'preliminary', NULL, 'Twenty-six older adults; the lens MOB (walking and balance limitation) is assigned from the use of a cane or rolling walker: the abstract names the group by age and device, and no identity in the vocabulary names older adults. Incline angle not stated in the abstract. Abstract read only (no full text); skimmed, so the finding sets no value and confirms nothing. [VERBATIM-EXEMPT: the persisted PubMed XML spells the less-than-or-equal sign as the character reference &#x2264; (p&#x2264;.05); the quote is the decoded text and the only mismatch is that spelling]', '2026-10-30 21:42', 'session_2026-10-30-ramp-spec-pages-rebuild', '2026-10-30 21:42', 'session_2026-10-30-ramp-spec-pages-rebuild', 'finding', NULL);
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (82, 91, 'NAMES-EXISTING', 'TERM-091', 'Singapore Code on Accessibility 2025, clause 4.6.5.2(b): landings are ''provided at regular intervals based on the gradient provided and the run of the ramp must not be more than what is shown in Table 5'', whose column is headed ''Maximum run of ramp (mm)''. The run is the length between landings, which is TERM-091''s definition (the horizontal length of a single ramp flight between landings). [ASSUMPTION: ''run'' here means the horizontal length, as the table''s values (6000 to 18000 mm at 1:12 to 1:24) and Figure 32 (''Max run in accordance with Table 5'', drawn between landings) show; the clause does not say ''horizontal''.] Warrant: the persisted PDF, page 47, rendered and read.', '2026-10-30 21:44', 'session_2026-10-30-ramp-spec-pages-rebuild', '2026-10-30 21:44', 'session_2026-10-30-ramp-spec-pages-rebuild');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (83, 93, 'NAMES-EXISTING', 'TERM-089', 'Lenker et al. 2016 abstract: ''access ramps used in transit vehicles'', tested at four slopes. A transit-bus boarding ramp is a built inclined surface that bridges a level difference on a route, which is TERM-089''s definition. [ASSUMPTION: TERM-089''s scope is read to include a vehicle boarding ramp; its definition excludes the running slope of paths and does not mention vehicles, and the owner''s ledger marks the reading of ''ramp'' terms as unratified.] Warrant: the abstract on the persisted landing page; no full text was read.', '2026-10-30 21:44', 'session_2026-10-30-ramp-spec-pages-rebuild', '2026-10-30 21:44', 'session_2026-10-30-ramp-spec-pages-rebuild');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (84, 92, 'DEFERRED', NULL, 'Hashizume et al. 2015 abstract: ''a long slope with 120m distance and 8% gradient'' on a sidewalk, with wheelchair users propelling it. It is a continuous slope of 120 m with no landing, so it is neither TERM-091 (a flight between landings) nor TERM-001 on its face; whether it names an existing term, a new one (continuous slope length) or none is the owner''s to rule. Left unadjudicated by this session.', '2026-10-30 21:44', 'session_2026-10-30-ramp-spec-pages-rebuild', '2026-10-30 21:44', 'session_2026-10-30-ramp-spec-pages-rebuild');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (85, 94, 'DEFERRED', NULL, 'Har-Nir et al. 2023 abstract: ''level, uphill and downhill slopes'' of a treadmill, walked by people with multiple sclerosis. A treadmill slope is an experimental condition, not a built ramp (TERM-089) and not stated as a design gradient (TERM-001); whether the phrase names any term is the owner''s to rule. Left unadjudicated by this session.', '2026-10-30 21:44', 'session_2026-10-30-ramp-spec-pages-rebuild', '2026-10-30 21:44', 'session_2026-10-30-ramp-spec-pages-rebuild');
INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (86, 95, 'DEFERRED', NULL, 'Liu et al. 2023 abstract and title: walking ''up and down an incline'' with a cane and a rolling walker; the angle is not given. An incline walked in a gait laboratory is an experimental condition, not a built ramp (TERM-089) and not a stated design gradient (TERM-001); whether the phrase names any term is the owner''s to rule. Left unadjudicated by this session.', '2026-10-30 21:44', 'session_2026-10-30-ramp-spec-pages-rebuild', '2026-10-30 21:44', 'session_2026-10-30-ramp-spec-pages-rebuild');
