INSERT INTO "extraction_relations" ("relation_id", "from_extraction_id", "relation", "to_extraction_id", "to_label", "to_kind", "stated", "input_role", "quote", "notes", "created_at", "created_by_session") VALUES (49, 133, 'condition_on', 100, NULL, NULL, 'named', NULL, 'La pendiente longitudinal máxima será del 10% para tramos de hasta 3,00 m de longitud, y del 8% para tramos de hasta 9,00 m de longitud, medidos en proyección horizontal.', NULL, '2026-10-30 21:42', 'session_2026-10-30-ramp-spec-pages-rebuild');
INSERT INTO "extraction_relations" ("relation_id", "from_extraction_id", "relation", "to_extraction_id", "to_label", "to_kind", "stated", "input_role", "quote", "notes", "created_at", "created_by_session") VALUES (50, 134, 'condition_on', 109, NULL, NULL, 'named', NULL, 'Ter uma inclinação não superior a 6 %, vencer um desnível não superior a 0,6 m e ter uma projecção horizontal não superior a 10 m', NULL, '2026-10-30 21:42', 'session_2026-10-30-ramp-spec-pages-rebuild');
INSERT INTO "extraction_relations" ("relation_id", "from_extraction_id", "relation", "to_extraction_id", "to_label", "to_kind", "stated", "input_role", "quote", "notes", "created_at", "created_by_session") VALUES (51, 135, 'condition_on', 110, NULL, NULL, 'named', NULL, 'Ter uma inclinação não superior a 8 %, vencer um desnível não superior a 0,4 m e ter uma projecção horizontal não superior a 5 m', NULL, '2026-10-30 21:42', 'session_2026-10-30-ramp-spec-pages-rebuild');
INSERT INTO "extraction_relations" ("relation_id", "from_extraction_id", "relation", "to_extraction_id", "to_label", "to_kind", "stated", "input_role", "quote", "notes", "created_at", "created_by_session") VALUES (52, 136, 'condition_on', 121, NULL, NULL, 'named', NULL, 'En cas de plan incliné de pente supérieure ou égale à 5 %, un palier de repos est nécessaire tous les 10 m.', NULL, '2026-10-30 21:42', 'session_2026-10-30-ramp-spec-pages-rebuild');
INSERT INTO "extraction_relations" ("relation_id", "from_extraction_id", "relation", "to_extraction_id", "to_label", "to_kind", "stated", "input_role", "quote", "notes", "created_at", "created_by_session") VALUES (53, 137, 'condition_on', 122, NULL, NULL, 'named', NULL, 'Il est recommandé de prévoir un palier de repos tous les 10 m dès qu’une pente supérieure à 2 % est aménagée sur une longue distance, sans attendre le seuil réglementaire de 5 %', NULL, '2026-10-30 21:42', 'session_2026-10-30-ramp-spec-pages-rebuild');
